-- Ignore maximize requests from all apps. You'll probably like this.

hl.window_rule({
    name  = "suppress-maximize-events",
    match = {
        class = ".*",
    },
    suppress_event = "maximize",
})

hl.window_rule({
    name  = "fix-xwayland-drags",
    match = {
        class = "^$",
        title = "^$",
        xwayland = true,
        float = true,
        fullscreen = false,
        pin = false,
    },
    no_focus = true,
})

-- Hyprland-run windowrule

hl.window_rule({
    name  = "move-hyprland-run",
    match = {
        class = "hyprland-run",
    },
    move = { 20, "monitor_h-120" },
    float = true,
})

-- Terminal transparency handled by kitty's background_opacity in kitty.conf

-- Cava visualizer — full opacity for the bars

hl.window_rule({
    name  = "cava-opacity",
    match = {
        class = "^scratch-cava$",
    },
    opacity = "1.0 1.0",
})

-- Screensaver — fullscreen terminal eye candy

hl.window_rule({
    name  = "screensaver-fullscreen",
    match = {
        class = "^screensaver$",
    },
    fullscreen = 1,
    no_anim = true,
    opacity = "1.0 1.0",
})

-- Autostart
hl.on("hyprland.start", function()
    hl.exec_cmd("waybar & waybar -c ~/.config/waybar/config-dp3.jsonc & awww-daemon & /usr/lib/polkit-kde-authentication-agent-1")
    hl.exec_cmd("sleep 1 && awww img ~/Pictures/Wallpapers/Lets_All_Love_Lain.jpeg")
    hl.exec_cmd("systemctl --user enable --now discord-mpris-rs.service")
    hl.exec_cmd("wl-paste --type text --watch cliphist store & wl-paste --type image --watch cliphist store")
    hl.exec_cmd("/usr/bin/pypr")
    hl.exec_cmd("pkill -f dunst|mako 2>/dev/null; swaync")
    hl.exec_cmd("sleep 1 && swaync-client -d")
end)
